import React from "react";
import styled from "styled-components";

const Wrapper = styled.div`
  margin-top: 28px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  background: linear-gradient(120deg, rgba(0, 70, 42, 0.08), rgba(0, 70, 42, 0.02));
  border: 1px solid ${({ theme }) => theme.colors.borderColor};
  border-radius: 16px;
  padding: 20px 22px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.06);
`;

const Pill = styled.span`
  display: inline-flex;
  align-items: center;
  padding: 8px 14px;
  border-radius: 999px;
  background: ${({ theme }) => theme.colors.backgroundWhite};
  color: ${({ theme }) => theme.colors.primary};
  font-weight: 800;
  letter-spacing: 0.01em;
  border: 1px solid ${({ theme }) => theme.colors.borderColor};
  width: fit-content;
`;

const Heading = styled.h2`
  margin: 0;
  font-size: 1.35rem;
  color: ${({ theme }) => theme.colors.textPrimary};
  letter-spacing: -0.01em;
`;

const Note = styled.p`
  margin: 0;
  color: ${({ theme }) => theme.colors.textSecondary};
  line-height: 1.6;
`;

interface ComingSoonProps {
  label: string;
  note?: string;
}

const ComingSoon: React.FC<ComingSoonProps> = ({ label, note }) => {
  return (
    <Wrapper>
      <Pill>{label}</Pill>
      <Heading>To be updated soon</Heading>
      <Note>{note || "Full details will be added here shortly. Thanks for your patience!"}</Note>
    </Wrapper>
  );
};

export default ComingSoon;
